local UIDisasterResponseChapterNode = Class('UIDisasterResponseChapterNode')

function UIDisasterResponseChapterNode:__init()
end

function UIDisasterResponseChapterNode:__delete()
end

function UIDisasterResponseChapterNode:Awake()
    SetButtonAction(self.Btn, function()
        if self:GetClickCB() then
            self:GetClickCB()(self:GetCellDt().id)
        end
    end)
end


function UIDisasterResponseChapterNode:OnDestroy()
    self.controller = nil--luabehaviour 中CSharp对象
    self:Delete()
    self = nil
end

-------------------------------------------------- get/set
---@return QuestSeniorEquipTypeVo
function UIDisasterResponseChapterNode:GetCellDt()
    return checkTable(self._cellDt)
end

function UIDisasterResponseChapterNode:GetClickCB()
    return self._clickCB
end
function UIDisasterResponseChapterNode:SetClickCB(handler)
    self._clickCB = handler
end

-------------------------------------------------- public
function UIDisasterResponseChapterNode:RefreshSelf(data, isSelected)
    self._cellDt   = checkTable(data)

    -- update icon
    CfUtils.FillImage(self.ImgBg1, self:GetCellDt().enterImage)

    -- update text
    CfUtils.FillText(self.TxtTitle, self:GetCellDt().name)

    -- update select
    self:RefreshSelectedStatus(isSelected)
end

function UIDisasterResponseChapterNode:RefreshSelectedStatus(status)
    -- TODO 选中后的层级问题
    if status then
        CfUtils.PlayAnimator(self.controller.gameObject, "Open")
    else
        CfUtils.PlayAnimator(self.controller.gameObject, "Default")
    end
end

return UIDisasterResponseChapterNode
 
 